// Demo-mode API router: answers the REST surface of server.js from bundled
// synthetic fixtures (frontend/src/demo/fixtures.json — generated by
// scripts/build-demo-fixtures.mjs, which runs the real backend over the
// sample logs in frontend/demo/sample-logs, so shapes match exactly).
//
// Served for claude-code / codex / omp: session list + detail, spawned
// sub-agent children (omp), insights, prompts, global search (multi-keyword
// AND over fixture transcripts). All
// mutating requests are rejected — the demo is read-only.

import type {
  ChildAgentSummary,
  Insights,
  PlatformCapabilities,
  PlatformInfo,
  PromptsData,
  SearchResult,
  SessionDetail,
  SessionSummary,
  SpawnLink,
} from '@/api/types';
import fixtures from './fixtures.json';

// --- Demo 平台注册表（与 DemoFixtures.session 的 claude-code/codex/omp 三平台对齐）。
// 真实后端为 GET /api/platforms 单一真源；demo 下 usePlatforms 被禁用（store 直接用
// 降级表），此处 stub 仅保证 API 面完整、被意外请求时形态一致。
const BASE_DEMO_CAPS: PlatformCapabilities = {
  list: true, find: false, parse: false, getSession: true,
  collectFiles: false, watchParse: false, needsAgent: false, listForAgent: false,
  listAllAgents: false, listAgents: false, children: false, spawn: false,
  watch: true, search: true, insights: true, prompts: true, toolAudit: false,
  inspect: false, otlp: false,
};

function demoPlatform(
  id: string,
  label: string,
  caps: Partial<PlatformCapabilities>,
  dirKey: string,
  dirLabel: string,
  dirHint: string,
  dirParam: string,
  color: string,
  defaultDir: string,
): PlatformInfo {
  return {
    id,
    label,
    origin: 'package',
    builtin: true,
    overrides: null,
    replacementPending: false,
    mounted: true,
    configuredMounted: true,
    restartRequired: false,
    capabilities: { ...BASE_DEMO_CAPS, ...caps },
    resume: caps.spawn ? true : false,
    create: caps.spawn ? true : false,
    bin: caps.spawn ? id : null,
    dirSettingKey: dirKey,
    dirSettingLabel: dirLabel,
    dirSettingHint: dirHint,
    dirParam,
    defaultDir,
    color,
    broken: false,
  };
}

const DEMO_PLATFORMS: PlatformInfo[] = [
  demoPlatform('codex', 'Codex', { spawn: true }, 'codexDir', 'Codex 会话目录', 'Codex 会话日志目录', 'dirCodex', '#58a6ff', '~/.codex/sessions'),
  demoPlatform('claude-code', 'Claude Code', { spawn: true, children: true }, 'claudeCodeDir', 'Claude Code 会话目录', 'Claude Code 项目会话目录', 'dirClaude', '#d2a8ff', '~/.claude/projects'),
  demoPlatform('omp', 'OMP', { spawn: true, children: true }, 'ompDir', 'OMP 会话目录', 'OMP（oh-my-pi）会话目录', 'dirOmp', '#ffd33d', '~/.omp/agent/sessions'),
];

interface DemoFixtures {
  sessions: Record<string, SessionSummary[]>;
  details: Record<string, SessionDetail>;
  children: Record<string, ChildAgentSummary[]>;
  childDetails: Record<string, SessionDetail>;
  insights: Record<string, Insights>;
  prompts: Record<string, PromptsData>;
  spawnMap: SpawnLink[];
}

const data = fixtures as unknown as DemoFixtures;

function emptyInsights(): Insights {
  return {
    totalSessions: 0,
    totalMessages: 0,
    totalToolCalls: 0,
    totalCost: 0,
    errorRate: 0,
    tokenUsage: {},
    toolStats: [],
    errorClusters: [],
    trend: [],
  };
}

function emptyPrompts(platform: string): PromptsData {
  return { platform, totalPrompts: 0, totalSessions: 0, groups: [] };
}

// 真实后端的 SessionSummary 带状态（status 四态）；demo fixtures 生成时不带，这里
// 按 fixture 顺序轮换补上，使任务看板四列与侧栏状态徽标在 demo 下可演示。
const DEMO_STATUSES = ['awaiting-input', 'working', 'waiting', 'stopped'];

function withDemoStatuses(list: SessionSummary[]): SessionSummary[] {
  // 已带 status 的条目保留原值（防御：fixtures 缺省不带，看板在 demo 下靠轮换补）。
  return list.map((s, i) => ({ ...s, status: s.status || DEMO_STATUSES[i % DEMO_STATUSES.length] }));
}

// --- Demo search: same semantics as lib/search.js (multi-keyword AND,
// case-insensitive, snippet ±(40/60) chars around the first keyword hit),
// evaluated over the bundled session transcripts.

function textOfMessage(msg: SessionDetail['messages'][number]): string {
  return (msg.content || [])
    .map((c) => (typeof c.text === 'string' ? c.text : ''))
    .filter(Boolean)
    .join('\n');
}

function extractSnippet(text: string, keyword: string): string {
  const idx = text.toLowerCase().indexOf(keyword);
  if (idx === -1) return '';
  const start = Math.max(0, idx - 40);
  const end = Math.min(text.length, idx + keyword.length + 60);
  return (start > 0 ? '…' : '') + text.slice(start, end).replace(/\s+/g, ' ').trim() + (end < text.length ? '…' : '');
}

function searchFixtures(q: string): SearchResult[] {
  const keywords = q.toLowerCase().split(/\s+/).filter(Boolean);
  if (!keywords.length) return [];
  const results: SearchResult[] = [];
  for (const [key, detail] of Object.entries(data.details)) {
    const slash = key.indexOf('/');
    const platform = key.slice(0, slash);
    const sessionId = key.slice(slash + 1);
    const fullText = detail.messages.map(textOfMessage).join('\n').toLowerCase();
    if (!keywords.every((kw) => fullText.includes(kw))) continue;
    const matches: SearchResult['matches'] = [];
    for (const msg of detail.messages) {
      if (matches.length >= 3) break;
      const text = textOfMessage(msg);
      const snippet = extractSnippet(text, keywords[0]);
      if (snippet) matches.push({ role: msg.role, snippet, timestamp: msg.timestamp ?? null });
    }
    if (matches.length) {
      results.push({
        sessionId,
        file: (data.sessions[platform]?.find((s) => s.id === sessionId)?.file as string) || `${sessionId}.jsonl`,
        platform,
        matches,
      });
    }
  }
  return results;
}

// 演示用 resume 命令串（与真实后端 buildResumeCommand 的内置平台参数一致，但不含
// POSIX/PowerShell 分支——demo 在浏览器里按 POSIX 形态展示即可）。无契约平台返回 null。
function resumeDemoCommand(platform: string, id: string, cwd: string): string | null {
  let cmd: string | null = null;
  if (platform === 'codex') cmd = `codex resume ${id} --yolo`;
  else if (platform === 'claude-code') cmd = `claude --dangerously-skip-permissions --resume ${id}`;
  else if (platform === 'omp') cmd = `omp --auto-approve --resume=${id}`;
  else if (platform === 'dsh') cmd = `dsh --profile pi-tui --preset standard --resume ${id}`;
  else if (platform === 'gemini') cmd = `gemini -r ${id} --approval-mode=yolo`;
  else if (platform === 'hermes') cmd = `hermes --resume ${id} --yolo`;
  return cmd === null ? null : cwd ? `cd ${cwd} && ${cmd}` : cmd;
}

export function demoJson<T>(url: string, init?: RequestInit): Promise<T> {
  const method = (init?.method || 'GET').toUpperCase();
  if (method !== 'GET') {
    return Promise.reject(new Error('Demo mode is read-only — run AgentLRay locally for the full experience.'));
  }

  const parsed = new URL(url, 'http://demo.local');
  const parts = parsed.pathname.split('/').filter(Boolean); // ['api', ...]
  const seg = (i: number) => decodeURIComponent(parts[i] || '');
  const ok = (value: unknown) => Promise.resolve(value as T);

  // /api/version — keep the stale-page poller quiet
  if (parsed.pathname === '/api/version') return ok({ bootId: 'demo' });

  // /api/platforms — demo 只含 fixture 覆盖的三平台；mt/replace 属写操作，
  // 已被上方 read-only 守卫拒绝。
  if (parsed.pathname === '/api/platforms') return ok(DEMO_PLATFORMS);

  // /api/:platform/agents — demo 无 agent 平台（均 needsAgent=false），返回空。
  if (seg(2) === 'agents') return ok([]);

  // /api/agents and /api/agents/:name/sessions[...] (openclaw — empty in demo)
  if (seg(1) === 'agents') {
    return ok(parts.length === 2 ? [] : []);
  }

  // Multi-platform aggregate: GET /api/sessions?platform=all|a,b
  if (parsed.pathname === '/api/sessions') {
    const platforms = data.sessions ?? {};
    const platformIds = Object.keys(platforms).filter((p) => Array.isArray(platforms[p]) && platforms[p].length);
    const total = platformIds.reduce((n, p) => n + (platforms[p]?.length || 0), 0);
    return ok({
      all: true,
      platformIds,
      total,
      offset: 0,
      limit: null,
      platforms: platformIds.map((p) => ({ platform: p, agent: null, total: platforms[p]?.length || 0, offset: 0, limit: null, sessions: withDemoStatuses(platforms[p] ?? []) })),
    });
  }

  if (parsed.pathname === '/api/insights') {
    const platform = parsed.searchParams.get('platform') || 'openclaw';
    return ok(data.insights[platform] ?? emptyInsights());
  }
  if (parsed.pathname === '/api/prompts') {
    const platform = parsed.searchParams.get('platform') || 'openclaw';
    return ok(data.prompts[platform] ?? emptyPrompts(platform));
  }
  if (parsed.pathname === '/api/prompts/hidden') return ok({ hidden: [] });
  if (parsed.pathname === '/api/search') return ok(searchFixtures(parsed.searchParams.get('q') || ''));
  if (parsed.pathname === '/api/spawn-map') return ok(data.spawnMap ?? []);
  if (seg(1) === 'spawn-tree') return ok({ node: null, parent: null });
  if (parsed.pathname === '/api/settings') {
    return ok({
      ui: { platform: null, selectedPlatforms: [] },
      cliBins: {
        codex: { bin: 'codex', configured: false, default: 'codex' },
        'claude-code': { bin: 'claude', configured: false, default: 'claude' },
        omp: { bin: 'omp', configured: false, default: 'omp' },
      },
      status: {
        recentActivityMs: { value: 120000, configured: false, default: 120000 },
        activeWorkCeilMs: { value: 1800000, configured: false, default: 1800000 },
        historyCeilMs: { value: 43200000, configured: false, default: 43200000 },
      },
      kanban: { maxPerStatus: { value: 20, configured: false, default: 20 } },
      llm: { baseUrl: '', model: '', hasApiKey: false, analysisTimeoutMs: 900000, backend: null },
      dirs: {
        codex: { key: 'codexDir', value: '', configured: false, envActive: false, default: '/root/.codex/sessions' },
        'claude-code': { key: 'claudeCodeDir', value: '', configured: false, envActive: false, default: '/root/.claude/projects' },
        omp: { key: 'ompDir', value: '', configured: false, envActive: false, default: '/root/.omp/agent/sessions' },
      },
      platforms: { default: null, ids: ['codex', 'claude-code', 'omp'], disabled: [], replaced: [] },
    });
  }

  // /api/:platform/sessions[/:id[/children[/:name]]]
  if (seg(2) === 'sessions') {
    const platform = seg(1);
    if (parts.length === 3) return ok(withDemoStatuses(data.sessions[platform] ?? []));
    if (parts.length === 4) {
      const detail = data.details[`${platform}/${seg(3)}`];
      if (detail) return ok(detail);
      return Promise.reject(new Error('Session not found in demo data'));
    }
    if (seg(4) === 'children') {
      if (parts.length === 5) return ok(data.children[`${platform}/${seg(3)}`] ?? []);
      const child = data.childDetails[`${platform}/${seg(3)}/${seg(5)}`];
      if (child) return ok(child);
      return Promise.reject(new Error('Child transcript not available in demo'));
    }
    if (seg(4) === 'resume-command') {
      // 与真实后端 /resume-command 同构（lib/resume.js buildResumeCommand）：演示
      // 用固定命令串。内置六平台可演示；其余（openclaw 等无 resume 契约）返回
      // supported:false，ResumeButton 据此不渲染按钮。
      const id = seg(3);
      const cwd = parsed.searchParams.get('cwd') || '';
      const cmd = resumeDemoCommand(platform, id, cwd);
      return ok({ supported: !!cmd, command: cmd });
    }
  }

  return Promise.reject(new Error('Not available in demo mode'));
}
